import { useCallback, useEffect, useState } from 'react';
import Head from 'next/head';
import { adminFetch, adminMutation, apiErrorMessage, toQuery } from '@/lib/admin-client';

type RequestRow = { id: string; user_id: string; type: 'export' | 'delete'; status: 'requested' | 'processing' | 'completed'; requested_by?: string; result_ref?: string; createdAt?: string; updatedAt?: string };
type Result = { data: RequestRow[]; total: number; page: number; pages: number; by_status: Record<string, number> };

export default function GdprPage() {
  const [result, setResult] = useState<Result>({ data: [], total: 0, page: 1, pages: 1, by_status: {} }); const [status, setStatus] = useState(''); const [page, setPage] = useState(1); const [userId, setUserId] = useState(''); const [type, setType] = useState<'export' | 'delete'>('export'); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState('');
  const load = useCallback(async () => { setLoading(true); setError(''); try { setResult(await adminFetch<Result>(`/gdpr/requests${toQuery({ status, page, limit: 25 })}`)); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر تحميل طلبات الخصوصية.')); } finally { setLoading(false); } }, [status, page]);
  useEffect(() => { void load(); }, [load]);
  async function create(event: React.FormEvent) { event.preventDefault(); if (!userId.trim()) return; if (type === 'delete' && !window.confirm('سيؤدي إكمال الطلب لاحقاً إلى إخفاء بيانات العميل وفق سياسة الحذف. إنشاء الطلب؟')) return; setSaving(true); try { await adminMutation('/gdpr/requests', 'POST', { user_id: userId.trim(), type }); setUserId(''); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر إنشاء طلب الخصوصية.')); } finally { setSaving(false); } }
  async function transition(row: RequestRow, action: 'start' | 'export/complete' | 'delete/complete') { const destructive = action === 'delete/complete'; if (destructive && !window.confirm(`سيتم إخفاء بيانات المستخدم ${row.user_id} وتسجيل العملية. تأكيد الإكمال؟`)) return; setSaving(true); try { await adminMutation(`/gdpr/${encodeURIComponent(row.id)}/${action}`, 'POST'); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر تنفيذ انتقال حالة GDPR.')); } finally { setSaving(false); } }
  return <><Head><title>خصوصية البيانات | نبض</title></Head><section dir="rtl" className="space-y-6 p-6 md:p-8"><header><h1 className="text-3xl font-bold">وحدة GDPR والخصوصية</h1><p className="mt-1 text-sm text-slate-500">تدار الطلبات كدورة حالة خادمية؛ لا تنفذ الإتاحة أو الحذف من تطبيق العميل.</p></header>{error ? <p role="alert" className="rounded-lg bg-rose-50 p-3 text-rose-700">{error}</p> : null}<form onSubmit={create} className="flex flex-wrap items-end gap-3 rounded-2xl border bg-white p-5 shadow-sm"><label className="text-sm">معرّف المستخدم<input value={userId} onChange={(e) => setUserId(e.target.value)} dir="ltr" required className="mt-1 block rounded-lg border p-2"/></label><label className="text-sm">الطلب<select value={type} onChange={(e) => setType(e.target.value as 'export' | 'delete')} className="mt-1 block rounded-lg border p-2"><option value="export">تصدير البيانات</option><option value="delete">حذف/إخفاء البيانات</option></select></label><button disabled={saving} className="rounded-lg bg-teal-700 px-4 py-2 text-sm font-bold text-white disabled:opacity-50">إنشاء الطلب</button></form><div className="flex flex-wrap items-center gap-2"><span className="text-sm text-slate-500">الحالة:</span><button onClick={() => { setStatus(''); setPage(1); }} className={`rounded px-3 py-1 text-sm ${!status ? 'bg-teal-700 text-white' : 'border'}`}>الكل</button>{Object.entries(result.by_status).map(([key, count]) => <button key={key} onClick={() => { setStatus(key); setPage(1); }} className={`rounded px-3 py-1 text-sm ${status === key ? 'bg-teal-700 text-white' : 'border'}`}>{key} ({count})</button>)}</div><div className="overflow-x-auto rounded-2xl border bg-white shadow-sm"><table className="min-w-full text-right text-sm"><thead className="bg-slate-50 text-xs text-slate-600"><tr><th className="p-4">الطلب</th><th className="p-4">المستخدم</th><th className="p-4">النوع</th><th className="p-4">الحالة</th><th className="p-4">آخر تحديث</th><th className="p-4">الإجراءات</th></tr></thead><tbody>{loading ? <tr><td colSpan={6} className="p-10 text-center text-slate-500">جارٍ تحميل طلبات الخصوصية…</td></tr> : result.data.length ? result.data.map((row) => <tr key={row.id} className="border-t"><td className="p-4 font-mono text-xs">{row.id}</td><td className="p-4 font-mono text-xs">{row.user_id}</td><td className="p-4">{row.type === 'export' ? 'تصدير' : 'حذف/إخفاء'}</td><td className="p-4">{row.status}</td><td className="p-4 text-xs">{row.updatedAt ? new Date(row.updatedAt).toLocaleString('ar-SA') : '—'}</td><td className="p-4">{row.status === 'requested' ? <button disabled={saving} onClick={() => void transition(row, 'start')} className="rounded border px-2 py-1 text-xs">بدء المعالجة</button> : null}{row.status === 'processing' && row.type === 'export' ? <button disabled={saving} onClick={() => void transition(row, 'export/complete')} className="rounded bg-teal-700 px-2 py-1 text-xs text-white">إكمال التصدير</button> : null}{row.status === 'processing' && row.type === 'delete' ? <button disabled={saving} onClick={() => void transition(row, 'delete/complete')} className="rounded bg-rose-700 px-2 py-1 text-xs text-white">إكمال الحذف</button> : null}{row.status === 'completed' ? <span className="text-xs text-slate-500">{row.result_ref || 'مكتمل'}</span> : null}</td></tr>) : <tr><td colSpan={6} className="p-10 text-center text-slate-500">لا توجد طلبات مطابقة.</td></tr>}</tbody></table></div><footer className="flex justify-between text-sm"><span>الإجمالي: {result.total}</span><div className="flex gap-2"><button className="rounded border px-3 py-1 disabled:opacity-40" disabled={page <= 1} onClick={() => setPage((value) => value - 1)}>السابق</button><span>{result.page} / {result.pages || 1}</span><button className="rounded border px-3 py-1 disabled:opacity-40" disabled={page >= (result.pages || 1)} onClick={() => setPage((value) => value + 1)}>التالي</button></div></footer></section></>;
}
